class FizzBuzz {
private:
    int n;
    int counter;
    mutex mtx;
    condition_variable cv;

public:
    FizzBuzz(int n) {
        this->n = n;
        counter = 1;
    }

    void fizz(function<void()> printFizz) {
        unique_lock<mutex> lk(mtx);
        while (counter <= n) {
            cv.wait(lk, [this]{ return counter > n || (counter % 3 == 0 && counter % 5 != 0); });
            if (counter > n) return;
            printFizz();
            counter++;
            cv.notify_all();
        }
    }

    void buzz(function<void()> printBuzz) {
        unique_lock<mutex> lk(mtx);
        while (counter <= n) {
            cv.wait(lk, [this]{ return counter > n || (counter % 5 == 0 && counter % 3 != 0); });
            if (counter > n) return;
            printBuzz();
            counter++;
            cv.notify_all();
        }
    }

    void fizzbuzz(function<void()> printFizzBuzz) {
        unique_lock<mutex> lk(mtx);
        while (counter <= n) {
            cv.wait(lk, [this]{ return counter > n || (counter % 15 == 0); });
            if (counter > n) return;
            printFizzBuzz();
            counter++;
            cv.notify_all();
        }
    }

    void number(function<void(int)> printNumber) {
        unique_lock<mutex> lk(mtx);
        while (counter <= n) {
            cv.wait(lk, [this]{ return counter > n || (counter % 3 != 0 && counter % 5 != 0); });
            if (counter > n) return;
            printNumber(counter);
            counter++;
            cv.notify_all();
        }
    }
};
